func (v Verdict) String() string {
	switch v {
	case VerdictOK:
		return "ok"
	case VerdictNoResult:
		return "no result"
	case VerdictRefused:
		return "unsupported or refused"
	case VerdictFailed:
		return "failed"
	}
	return "pending"
}

// Outcome is a verdict and its marks. Invariant: Partial is set only with ok
// or no result (a partial walk that found nothing is still "no result"), never
// with refused or failed.
type Outcome struct {
	Verdict Verdict
	Partial bool
	Skipped bool
}

